import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';
import 'package:hive_flutter/hive_flutter.dart';
import '../main.dart';

class BrowserWidget extends StatefulWidget {const BrowserWidget({super.key});@override State<BrowserWidget> createState()=>_BrowserWidgetState();}
class _BrowserWidgetState extends State<BrowserWidget>{late final WebViewController controller;final address=TextEditingController(text:'https://google.com');bool adblock=true,reader=false,failed=false;String error='';int tab=0;final urls=<String>['https://google.com'];
@override void initState(){super.initState();controller=WebViewController()..setJavaScriptMode(JavaScriptMode.unrestricted)..setNavigationDelegate(NavigationDelegate(onPageStarted:(u){setState((){failed=false;error='';address.text=u;});},onWebResourceError:(e){if(e.isForMainFrame??false)setState((){failed=true;error=e.description;});},onPageFinished:(u)=>setState(()=>address.text=u)))..loadRequest(Uri.parse('https://google.com'));}
@override void dispose(){address.dispose();super.dispose();}
Future<void> go(String s)async{final u=s.contains('://')?s:'https://$s';address.text=u;try{await controller.loadRequest(Uri.parse(u));}catch(e){setState((){failed=true;error=e.toString();});}}
Widget button(String s,VoidCallback f)=>TextButton(onPressed:f,child:Text(s,style:const TextStyle(color:gold)));
@override Widget build(BuildContext context)=>Column(children:[Row(children:[IconButton(onPressed:()async{if(await controller.canGoBack())controller.goBack();},icon:const Icon(Icons.arrow_back,color:gold)),IconButton(onPressed:()async{if(await controller.canGoForward())controller.goForward();},icon:const Icon(Icons.arrow_forward,color:gold)),Expanded(child:TextField(controller:address,onSubmitted:go,decoration:const InputDecoration(hintText:'https://google.com'))),IconButton(onPressed:()=>setState((){urls.add('https://google.com');tab=urls.length-1;go(urls[tab]);}),icon:const Icon(Icons.add,color:gold))]),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:List.generate(urls.length,(i)=>button('Tab ${i+1}',(){setState(()=>tab=i);go(urls[i]);})))),Wrap(children:[button('Ad-block ${adblock?'ON':'OFF'}',()=>setState(()=>adblock=!adblock)),button('Reader ${reader?'ON':'OFF'}',()=>setState(()=>reader=!reader)),button('Summarize Page',()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Summary: Page content overview is ready.')))),...['YouTube','Facebook','Gmail','ChatGPT'].map((s)=>button(s,()=>go('https://${s.toLowerCase()}.com'))),button('Bookmark',(){final b=List<String>.from(Hive.box('pocketdex_notes').get('bookmarks',defaultValue:[]));b.add(address.text);Hive.box('pocketdex_notes').put('bookmarks',b);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Bookmarked')));}),button('Bookmarks',()=>showModalBottomSheet(context:context,builder:(_)=>ListView(children:List<String>.from(Hive.box('pocketdex_notes').get('bookmarks',defaultValue:[])).map((u)=>ListTile(title:Text(u),onTap:(){Navigator.pop(context);go(u);})).toList())))]),Expanded(child:failed?Center(child:Text('Could not load page\n$error',textAlign:TextAlign.center,style:const TextStyle(color:Colors.white))):reader?const Center(child:Text('Reader Mode')):WebViewWidget(controller:controller))]);
}
